{
  "application": "report-generation",
  "case_id": "case-air-jordan-resale-market-analysis-en",
  "language": "en",
  "report": {
    "type": "market-analysis-report",
    "audience": "analyst",
    "tone": "analytical, data-forward, detailed"
  },
  "brief": {
    "title": "Air Jordan Sneaker Resale Market Analysis (2023–2026)",
    "one_liner": "A comprehensive analysis of 5,000 Air Jordan secondary-market transactions examining pricing dynamics, profit margins, inventory velocity, and channel performance across models, colorways, and conditions.",
    "goal": "Equip analysts and resale market strategists with actionable insights into which Jordan models, colorways, and sales channels yield the highest margins, how shoe condition affects resale value, and how inventory turnover varies across platforms — enabling data-driven sourcing and pricing decisions."
  },
  "required_sections": [
    {
      "section_id": "market-overview",
      "title": "Market Overview & Transaction Summary",
      "objective": "Provide a high-level summary of total transactions, date range coverage, average retail vs. resale prices, and overall profit margin distribution."
    },
    {
      "section_id": "model-colorway-analysis",
      "title": "Performance by Shoe Model & Colorway",
      "objective": "Rank Air Jordan models and colorways by average resale price, profit margin, and transaction volume. Identify the highest-premium and below-retail segments."
    },
    {
      "section_id": "condition-impact",
      "title": "Impact of Shoe Condition on Resale Value",
      "objective": "Quantify how Deadstock, VNDS, and Used conditions affect resale price premiums and the probability of selling above retail."
    },
    {
      "section_id": "channel-performance",
      "title": "Sales Channel Performance & Inventory Velocity",
      "objective": "Compare sales channels (StockX, GOAT, kick hub 2026, Stadium Goods, walk-in retail, etc.) on average resale price, profit margin, and days in inventory to determine which platforms move product fastest and most profitably."
    },
    {
      "section_id": "time-trends",
      "title": "Temporal Trends & Seasonality",
      "objective": "Analyze monthly and yearly trends in resale prices, profit margins, and transaction volumes to identify seasonal patterns and market momentum shifts from 2023 to 2026."
    },
    {
      "section_id": "strategic-recommendations",
      "title": "Key Findings & Strategic Recommendations",
      "objective": "Synthesize insights into actionable recommendations for resellers regarding model selection, optimal sales channels, inventory holding periods, and timing strategies."
    }
  ],
  "kpis": [
    {
      "name": "Average Profit Margin (USD)",
      "description": "Mean difference between Resale_Price_USD and Retail_Price_USD across all transactions, indicating overall market profitability."
    },
    {
      "name": "Resale Premium Rate",
      "description": "Percentage of transactions where Resale_Price_USD exceeds Retail_Price_USD, measuring how often resellers achieve a profit."
    },
    {
      "name": "Average Days in Inventory",
      "description": "Mean number of days a sneaker sits before being sold, reflecting inventory turnover speed."
    },
    {
      "name": "Average Resale-to-Retail Ratio",
      "description": "Mean ratio of Resale_Price_USD to Retail_Price_USD, expressing the typical markup or discount as a multiplier."
    },
    {
      "name": "Top-Performing Colorway Margin",
      "description": "The highest average profit margin achieved by any single colorway, highlighting the most lucrative product."
    }
  ],
  "analysis_dimensions": [
    "Shoe_Model",
    "Colorway",
    "Condition",
    "Sales_Channel",
    "Sale_Date"
  ]
}

